export function CreateBlueprintDialog() {
    const [open, setOpen] = useState(false);
    const form = useForm({
        name: "",
        school_year: "",
    });

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        form.post(store.url(), {
            preserveScroll: true,
            onSuccess: () => {
                form.reset();
                setOpen(false);
            },
        });
    };

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                <Button>
